                                            <tr>
                                                <td class="label" style="padding: 3px;font-weight: bold;">
                                                    End                                                </td>
                                                <td style="padding: 3px;">
                                                    28/07/2026 8:45 am
                                                </td>
                                            </tr>
                                            <tr>
                                                <td class="label" style="padding: 3px;font-weight: bold;">
                                                    Timezone                                                </td>
                                                <td style="padding: 3px;">
                                                    Berlin (+1:00)                                                </td>
                                            </tr>

                                                                                            <tr>
                                                    <td class="label" style="padding: 3px;font-weight: bold;">
