                                        <br>

                                        <h2 style="text-align: center;">
                                            Customer Details                                        </h2>

                                        <table id="customer-details" class="details-table" align="center">
                                                                                            <tr>
                                                    <td class="label" style="padding: 3px;font-weight: bold;">
